219: export function injectStyles() {
220:   if (typeof document === 'undefined') return;
221:   if (document.getElementById('weather-card-style')) return;
222:   const style = document.createElement('style');
223:   style.id = 'weather-card-style';
224:   style.textContent = CARD_CSS;
